// Dharma scenes for the illustration kit (21 Oct 2026): the models that the Gita and the Upanishads teach, drawn in code
// for the spiritual channel. Same stage, same rules as the rest of the kit: landscape 1920x1080, every word on screen comes
// from the scene's props, no deity is ever drawn, nothing is generated by an image model.
//   verse    a verse on a paper card: Devanagari, transliteration, the English line, the source (text from corpus.py)
//   chariot  Katha Upanishad 1.3.3-4: body = chariot, intellect = driver, mind = reins, senses = horses, self = rider
//   birds    Mundaka Upanishad 3.1.1: two birds on one tree; one eats the fruit, the other only watches
//   tree     Gita 15.1-3: the ashvattha with roots above and branches below, cut with the axe of non-attachment
//   gunas    the three gunas as a meter: bars that fill as each one is named
//   rope     the rope and the snake: in the dark a rope is a snake; bring the lamp and the snake was never there
//   salt     Chandogya Upanishad 6.13: a lump of salt in water: dissolved, unseen, in every drop
// Icons (100 x 100 box like the kit's): diya, lotus, chariot, bow, flute, feather, banyan, conch.
import React from "react";
import {Easing, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig} from "remotion";
import {SP, P, IStage, IHeading, INote, IStamps, Pop, Chip, Arrow, PersonIcon, TFn, fit, clamp01, SAFE} from "./kit";
import {COND, TYPE} from "../../voxkit";

// ---------- fonts for scripture: Noto Serif Devanagari and Noto Serif (both OFL, in public/fonts) ----------
export const DEVA = "'Noto Serif Devanagari', 'Noto Sans Devanagari', 'DejaVu Serif', serif";
export const SERIF = "'Noto Serif', 'DejaVu Serif', Georgia, serif";
export const DharmaFonts: React.FC = () => (
  <style>{`@font-face{font-family:'Noto Serif Devanagari';src:url(${staticFile("fonts/NotoSerifDevanagari.ttf")}) format("truetype");}
@font-face{font-family:'Noto Serif';src:url(${staticFile("fonts/NotoSerif.ttf")}) format("truetype");}`}</style>
);

// ---------- palette additions for the channel (the kit's P stays the base) ----------
export const DP = {indigo: "#2B2F6B", saffron: P.orange, lotus: "#D98BA3", lotusLt: "#EBB7C6", water: "#9FC5D8", waterLt: "#C6DEE9",
  bark: "#8B6A3E", barkLt: "#B08A55", leaf: P.green, leafLt: "#6FA37A", sky: "#DCE8EE", night: "#141A33", terracotta: "#B9633A", rope: "#C8A165"};

// ---------- shared helpers (same conventions as World.tsx) ----------
const arr = (x: any): any[] => (Array.isArray(x) ? x : []);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const prog = (f: number, start: number, dur: number, ease: (t: number) => number = Easing.out(Easing.cubic)) =>
  interpolate(f, [start, start + Math.max(1, dur)], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease});
const pop = (f: number, fps: number, start: number, damping = 11, stiffness = 150) =>
  f < start ? 0 : spring({frame: f - start, fps, config: {damping, stiffness, mass: 0.8}});
const ON = -1000;   // "on from the start"
const when = (T: TFn, x: any) => (x == null || x === 0 ? ON : T(x));
const Txt: React.FC<{x: number; y: number; text: string; size: number; color?: string; anchor?: "start" | "middle" | "end"; font?: string; weight?: number; italic?: boolean; opacity?: number}> =
  ({x, y, text, size, color = P.ink, anchor = "middle", font = COND, weight = 700, italic = false, opacity = 1}) =>
  <text x={x} y={y} fontFamily={font} fontWeight={weight} fontStyle={italic ? "italic" : "normal"} fontSize={size} textAnchor={anchor} fill={color} opacity={opacity} letterSpacing={font === COND ? 1 : 0}>{text}</text>;
// Greedy word wrap on an estimated glyph width (k = average width as a fraction of the size).
const wrap = (text: string, size: number, maxW: number, k = 0.5): string[] => {
  const out: string[] = []; let line = "";
  for (const w of String(text).split(/\s+/).filter(Boolean)) {
    const t = line ? `${line} ${w}` : w;
    if (t.length * size * k > maxW && line) { out.push(line); line = w; } else line = t;
  }
  if (line) out.push(line);
  return out;
};
// A labelled part: a chip that pops at `start` and an arrow that draws itself from the chip to the part.
const Label: React.FC<{x: number; y: number; start: number; text?: string; to?: [number, number]; anchor?: "start" | "middle" | "end"; size?: number; fill?: string; color?: string; bend?: number}> =
  ({x, y, start, text, to, anchor = "start", size = 40, fill, color, bend = 0}) => {
  if (!text) return null;
  const w = text.length * size * 0.52 + size * 0.9;
  const ex = anchor === "start" ? x + w + 10 : anchor === "end" ? x - w - 10 : x;
  return (
    <g>
      {to ? <Arrow x1={ex} y1={y} x2={to[0]} y2={to[1]} start={start + 4} dur={14} width={6} bend={bend}/> : null}
      <Chip x={x} y={y} start={start} text={text} size={size} anchor={anchor} fill={fill} color={color}/>
    </g>
  );
};
// Deterministic pseudo-random in [0, 1): the same picture on every render.
const rnd = (i: number, salt = 0) => { const v = Math.sin(i * 127.1 + salt * 311.7) * 43758.5453; return v - Math.floor(v); };

// ---------- icons ----------
type IP = {x?: number; y?: number; size?: number; color?: string; accent?: string};
const Ico: React.FC<IP & {children: React.ReactNode}> = ({x = 0, y = 0, size = 100, children}) =>
  <g transform={`translate(${x} ${y}) scale(${size / 100})`} strokeLinejoin="round" strokeLinecap="round">{children}</g>;
const SW = 4;
// A clay lamp. The flame breathes.
